const dt = gdjs.evtTools.runtimeScene.getElapsedTimeInSeconds(runtimeScene);

if (!global.CoreMechanics) {
  if (typeof require !== 'undefined') {
    try {
      global.CoreMechanics = require('./js/core_mechanics.js');
    } catch (e) {
      console.error(e);
    }
  }
  if (!global.CoreMechanics && typeof document !== 'undefined') {
    let scriptTag = document.getElementById('core-mechanics-script');
    if (!scriptTag) {
      scriptTag = document.createElement('script');
      scriptTag.id = 'core-mechanics-script';
      scriptTag.src = 'js/core_mechanics.js';
      scriptTag.async = false;
      document.head.appendChild(scriptTag);
    }
  }
  return;
}

if (!global._memoryManager) {
  global._memoryManager = new global.CoreMechanics.MemoryManager(100.0, 2.5);
}

global._memoryManager.updateMemoryLeak(dt, runtimeScene);

const cacheList = runtimeScene.getObjects('Cache');
if (cacheList.length > 0) {
  const cache = cacheList[0];
  const platformerBehavior = cache.getBehavior('PlatformerObject');
  const inputManager = runtimeScene.getGame().getInputManager();

  if (inputManager.isKeyPressed('Left')) {
    platformerBehavior.simulateControl('Left');
    if (cache.setFlippedX) cache.setFlippedX(true);
  }
  if (inputManager.isKeyPressed('Right')) {
    platformerBehavior.simulateControl('Right');
    if (cache.setFlippedX) cache.setFlippedX(false);
  }
  if (inputManager.isKeyPressed('Up')) {
    platformerBehavior.simulateControl('Jump');
  }

  if (gdjs.evtTools.input.wasKeyJustPressed(runtimeScene, 'x') || gdjs.evtTools.input.wasKeyJustPressed(runtimeScene, 'X')) {
    const floppy = runtimeScene.createObject('Disquete');
    if (floppy) {
      const initialX = cache.getX() + cache.getWidth() / 2;
      const initialY = cache.getY() + cache.getHeight() / 2;
      const velocity = 650;
      const facingLeft = cache.isFlippedX ? cache.isFlippedX() : false;
      const angle = facingLeft ? -135 : -45;

      floppy.setPosition(initialX, initialY);
      floppy._customPhysics = {
        x0: initialX,
        y0: initialY,
        v0: velocity,
        angleDegrees: angle,
        timeElapsed: 0
      };
    }
  }

  const ramSticks = runtimeScene.getObjects('RAM_Stick');
  for (let i = 0; i < ramSticks.length; i++) {
    const ramStick = ramSticks[i];
    if (gdjs.RuntimeObject.collisionTest(cache, ramStick, false)) {
      ramStick.deleteFromScene(runtimeScene);
      global.restoreIntegrity(runtimeScene);
    }
  }
}

const floppies = runtimeScene.getObjects('Disquete');
for (let i = 0; i < floppies.length; i++) {
  const floppy = floppies[i];
  if (floppy._customPhysics) {
    floppy._customPhysics.timeElapsed += dt;
    const traj = global.CoreMechanics.LegacyHardwarePhysics.calculateFloppyTrajectory(
      floppy._customPhysics.x0,
      floppy._customPhysics.y0,
      floppy._customPhysics.v0,
      floppy._customPhysics.angleDegrees,
      floppy._customPhysics.timeElapsed,
      980
    );
    floppy.setPosition(traj.x, traj.y);
    floppy.setAngle(traj.rotationAngle);

    if (traj.y > 2000 || traj.x < -500 || traj.x > 2500) {
      floppy.deleteFromScene(runtimeScene);
    }
  }
}

const bugs = runtimeScene.getObjects('Bug');
for (let i = 0; i < floppies.length; i++) {
  const floppy = floppies[i];
  for (let j = 0; j < bugs.length; j++) {
    const bug = bugs[j];
    if (gdjs.RuntimeObject.collisionTest(floppy, bug, false)) {
      floppy.deleteFromScene(runtimeScene);
      bug.deleteFromScene(runtimeScene);
      break;
    }
  }
}

const hudList = runtimeScene.getObjects('HUD_Text');
if (hudList.length > 0) {
  let integrityVal = 100;
  const globalVars = runtimeScene.getGame().getVariables();
  if (globalVars.has('Integridad_Datos')) {
    integrityVal = globalVars.get('Integridad_Datos').getAsNumber();
  }
  hudList[0].setString('Integridad de Datos: ' + Math.round(integrityVal) + '%');
}
